import React, { useState, useEffect } from "react";
import axios from "axios";
import QuestionCard from "./component/QuestionCard";
import "./App.css";

function App() {
  const [questions, setQuestions] = useState([]);
  const [hideAnswers, setHideAnswers] = useState(false);

  // Creates 5 slots with keys matching the first working version
  const createEmptyForm = () => Array(5).fill(null).map(() => ({ 
    question: "", 
    answer: "", 
    confirmAnswer: "" 
  }));

  const [qaList, setQaList] = useState(createEmptyForm());

  useEffect(() => {
    axios.get("http://localhost:3001/questions")
      .then((res) => {
        setQuestions(res.data);
      })
      .catch((err) => console.error("Fetch error:", err));
  }, []);

  const onChange = (index, field, value) => {
    const updated = [...qaList];
    updated[index][field] = value;
    setQaList(updated);
  };

  const getAvailableQuestions = (currentIndex) => {
    const usedQuestions = qaList
      .filter((_, idx) => idx !== currentIndex)
      .map(item => item.question);

    return questions.filter(q => !usedQuestions.includes(q.question));
  };

  const handleSubmit = async () => {
    const isComplete = qaList.every(q => q.question && q.answer && q.confirmAnswer);
    const isMatched = qaList.every(q => q.answer === q.confirmAnswer);

    if (!isComplete) return alert("Please fill all 5 questions.");
    if (!isMatched) return alert("Answers do not match.");

    try {
      await axios.post("http://localhost:3001/responses", { responses: qaList });
      alert("Success!");
      setQaList(createEmptyForm()); // Clears the form
    } catch (err) {
      alert("Error saving responses.");
    }
  };

  return (
    <div className="app-container">
      <div className="hide-toggle-container">
        <label>
          <input 
            type="checkbox" 
            checked={hideAnswers} 
            onChange={() => setHideAnswers(!hideAnswers)} 
          />
          Hide Answers
        </label>
      </div>

      <h1 className="app-title">Security Setup</h1>

      <div className="form-wrapper">
        {qaList.map((qa, i) => (
          <QuestionCard
            key={i}
            index={i}
            qa={qa}
            questions={getAvailableQuestions(i)}
            hideAnswers={hideAnswers} 
            onChange={onChange}
          />
        ))}

        <button className="submit-btn" onClick={handleSubmit}>
          Submit
        </button>
      </div>
    </div>
  );
}

export default App;
